GlassCoolingRackMaker.ironStock=14; GlassCoolingRackMaker.bronzeStock=12; GlassCoolingRackMaker.woodStock=14; GlassCoolingRackMaker.leatherStock=8; GlassCoolingRackMaker.silverStock=8; GlassCoolingRackMaker.goldStock=6; GlassCoolingRackMaker.jewelStock=4; GlassCoolingRackMaker.pearlStock=4
GlassCoolingRackMaker.productStock = {}; GlassCoolingRackMaker.buildings = {}; GlassCoolingRackMaker.maker = nil; GlassCoolingRackMaker.activeMaking = {}; GlassCoolingRackMaker.totalProducts = 0; GlassCoolingRackMaker.dayTimer = 0
function GlassCoolingRackMaker.init() GlassCoolingRackMaker.ironStock=14; GlassCoolingRackMaker.bronzeStock=12; GlassCoolingRackMaker.woodStock=14; GlassCoolingRackMaker.leatherStock=8; GlassCoolingRackMaker.silverStock=8; GlassCoolingRackMaker.goldStock=6; GlassCoolingRackMaker.jewelStock=4; GlassCoolingRackMaker.pearlStock=4; GlassCoolingRackMaker.productStock={}; GlassCoolingRackMaker.buildings={}; GlassCoolingRackMaker.maker=nil; GlassCoolingRackMaker.activeMaking={}; GlassCoolingRackMaker.totalProducts=0; GlassCoolingRackMaker.dayTimer=0; print("[GlassCoolingRackMaker] Royal Glass Cooling Rack Maker System initialized (6 products, 4 buildings)") end
function GlassCoolingRackMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassCoolingRackMaker.maker={name=n or ("Poličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Poličar najet: %s (spretnost: %d)",GlassCoolingRackMaker.maker.name,s),"success") end; return true end
function GlassCoolingRackMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassCoolingRackMaker.build(id) local ok,e=GlassCoolingRackMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassCoolingRackMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassCoolingRackMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassCoolingRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassCoolingRackMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassCoolingRackMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassCoolingRackMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassCoolingRackMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassCoolingRackMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassCoolingRackMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassCoolingRackMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassCoolingRackMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassCoolingRackMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassCoolingRackMaker.buildings==0 then return false,"Potrebna polična delavnica" end; if not GlassCoolingRackMaker.maker then return false,"Potreben poličar" end; return true end
function GlassCoolingRackMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassCoolingRackMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassCoolingRackMaker.ironStock=GlassCoolingRackMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassCoolingRackMaker.bronzeStock=GlassCoolingRackMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassCoolingRackMaker.woodStock=GlassCoolingRackMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassCoolingRackMaker.leatherStock=GlassCoolingRackMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassCoolingRackMaker.silverStock=GlassCoolingRackMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassCoolingRackMaker.goldStock=GlassCoolingRackMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassCoolingRackMaker.jewelStock=GlassCoolingRackMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassCoolingRackMaker.pearlStock=GlassCoolingRackMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassCoolingRackMaker.maker then t=math.max(1,t-math.floor(GlassCoolingRackMaker.maker.skill/13)) end; table.insert(GlassCoolingRackMaker.activeMaking,{id="glasscoolingrack_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassCoolingRackMaker.completeMaking(m) local q=1.0+(GlassCoolingRackMaker.getQualityBonus()/100); if GlassCoolingRackMaker.maker then q=q+(GlassCoolingRackMaker.maker.skill/140) end; q=math.min(2.5,q); GlassCoolingRackMaker.productStock[m.productType]=(GlassCoolingRackMaker.productStock[m.productType] or 0)+m.quantity; GlassCoolingRackMaker.totalProducts=GlassCoolingRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassCoolingRackMaker.maker then GlassCoolingRackMaker.maker.itemsMade=GlassCoolingRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassCoolingRackMaker.maker.skill=math.min(100,GlassCoolingRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscoolingrack.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassCoolingRackMaker.update(dt) if not _G.state then return end; GlassCoolingRackMaker.dayTimer=GlassCoolingRackMaker.dayTimer+dt; if GlassCoolingRackMaker.dayTimer>=30 then GlassCoolingRackMaker.dayTimer=0; for i=#GlassCoolingRackMaker.activeMaking,1,-1 do local m=GlassCoolingRackMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassCoolingRackMaker.completeMaking(m); table.remove(GlassCoolingRackMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassCoolingRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassCoolingRackMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassCoolingRackMaker.getStats() return {ironStock=GlassCoolingRackMaker.ironStock,bronzeStock=GlassCoolingRackMaker.bronzeStock,woodStock=GlassCoolingRackMaker.woodStock,leatherStock=GlassCoolingRackMaker.leatherStock,silverStock=GlassCoolingRackMaker.silverStock,goldStock=GlassCoolingRackMaker.goldStock,jewelStock=GlassCoolingRackMaker.jewelStock,pearlStock=GlassCoolingRackMaker.pearlStock,productStock=GlassCoolingRackMaker.productStock,numBuildings=#GlassCoolingRackMaker.buildings,hasMaker=GlassCoolingRackMaker.maker~=nil,makerName=GlassCoolingRackMaker.maker and GlassCoolingRackMaker.maker.name or "—",makerSkill=GlassCoolingRackMaker.maker and GlassCoolingRackMaker.maker.skill or 0,activeMaking=#GlassCoolingRackMaker.activeMaking,totalProducts=GlassCoolingRackMaker.totalProducts} end
return GlassCoolingRackMaker
